import{_ as e,C as a,c as o,o as t,j as s,b as i,a0 as r,a as n,w as l,G as d,a1 as c}from"./chunks/framework.DKRgXLPU.js";const m=JSON.parse('{"title":"Metas SMART para Petanca","description":"","frontmatter":{},"headers":[],"relativePath":"pt/education/goals/smart-goals.md","filePath":"pt/education/goals/smart-goals.md"}');const p=e({name:"pt/education/goals/smart-goals.md"},[["render",function(e,m,p,u,h,f){const v=a("Mermaid");return t(),o("div",null,[m[1]||(m[1]=s("h1",{id:"metas-smart-para-petanca",tabindex:"-1"},[n("Metas SMART para Petanca "),s("a",{class:"header-anchor",href:"#metas-smart-para-petanca","aria-label":'Permalink to "Metas SMART para Petanca"'},"​")],-1)),m[2]||(m[2]=s("p",null,"A metodologia SMART transforma desejos vagos em objetivos concretos. Vamos analisar cada elemento em detalhes, com exemplos específicos para a petanca.",-1)),m[3]||(m[3]=s("div",{class:"tip custom-block"},[s("p",{class:"custom-block-title"},"A Grande Ideia"),s("p",null,[s("strong",null,"Objetivos vagos levam a resultados vagos."),n(' Metas SMART criam clareza, ação e progresso mensurável. Transforme "Eu quero melhorar" em metas específicas que você realmente pode alcançar.')])],-1)),(t(),i(c,null,{default:l(()=>[d(v,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BObjetivo%20vago%5D%20--%3E%20B%5BNenhuma%20a%C3%A7%C3%A3o%20clara%5D%0A%20%20%20%20B%20--%3E%20C%5BSem%20progresso%5D%0A%0A%20%20%20%20D%5BMeta%20SMART%5D%20--%3E%20E%5BPlano%20de%20a%C3%A7%C3%A3o%20claro%5D%0A%20%20%20%20E%20--%3E%20F%5BProgresso%20mensur%C3%A1vel%5D%0A%20%20%20%20F%20--%3E%20G%5BConquista%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffebee%0A%20%20%20%20style%20C%20fill%3A%23ffebee%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20G%20fill%3A%23fff4e1%0A"})]),fallback:l(()=>[...m[0]||(m[0]=[n(" Loading... ",-1)])]),_:1})),m[4]||(m[4]=r('<h2 id="s-especifico" tabindex="-1">S - Específico <a class="header-anchor" href="#s-especifico" aria-label="Permalink to &quot;S - Específico&quot;">​</a></h2><p>Um objetivo específico responde a estas perguntas:</p><ul><li><strong>O que</strong> exatamente eu quero alcançar?</li><li><strong>Onde</strong> isso acontecerá?</li><li><strong>Quais</strong> aspectos estão envolvidos?</li></ul><h3 id="tornar-as-metas-especificas" tabindex="-1">Tornar as metas específicas. <a class="header-anchor" href="#tornar-as-metas-especificas" aria-label="Permalink to &quot;Tornar as metas específicas.&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Vago</th><th>Específico</th></tr></thead><tbody><tr><td>&quot;Aprimorar minha mira&quot;</td><td>&quot;Aprimorar minha precisão de apontamento em superfícies de cascalho a distâncias de 7 a 9 metros&quot;</td></tr><tr><td>&quot;Torne-se mentalmente mais forte&quot;</td><td>&quot;Desenvolva uma rotina pré-arremesso consistente que eu utilize em todos os arremessos.&quot;</td></tr><tr><td>&quot;Ganhe mais jogos&quot;</td><td>&quot;Ganhar pelo menos 60% das minhas partidas competitivas nesta temporada&quot;</td></tr></tbody></table><h3 id="lista-de-verificacao-de-especificidade" tabindex="-1">Lista de verificação de especificidade <a class="header-anchor" href="#lista-de-verificacao-de-especificidade" aria-label="Permalink to &quot;Lista de verificação de especificidade&quot;">​</a></h3><ul><li>[ ] Alguém consegue entender exatamente o que estou tentando fazer?</li><li>[ ] Defini as condições (distância, superfície, situação)?</li><li>[ ] Existe apenas uma interpretação para esse objetivo?</li></ul><h2 id="m-mensuravel" tabindex="-1">M - Mensurável <a class="header-anchor" href="#m-mensuravel" aria-label="Permalink to &quot;M - Mensurável&quot;">​</a></h2><p>O que não se mede, não se gerencia. Metas mensuráveis permitem acompanhar o progresso e saber quando se alcançou o sucesso.</p><h3 id="formas-de-medir-objetivos-na-petanca" tabindex="-1">Formas de medir objetivos na petanca <a class="header-anchor" href="#formas-de-medir-objetivos-na-petanca" aria-label="Permalink to &quot;Formas de medir objetivos na petanca&quot;">​</a></h3><p><strong>Medidas quantitativas:</strong></p><ul><li>Pontos obtidos em exercícios (ex.: 24/30)</li><li>Percentagem de precisão (ex.: taxa de acerto de 75%)</li><li>Distância do alvo (ex.: em média 30 cm do macaco)</li><li>Consistência (ex.: 3 sessões bem-sucedidas consecutivas)</li></ul><p><strong>Utilizando exercícios de treinamento como medidas:</strong></p><table tabindex="0"><thead><tr><th>Furar</th><th>O que mede</th><th>Exemplo de alvo</th></tr></thead><tbody><tr><td>Escada de tiro</td><td>Precisão de tiro sob pressão</td><td>Alcance 10m em 30 bolas</td></tr><tr><td>Precisão de apontamento</td><td>Precisão de apontamento para a zona</td><td>24/30 pontos</td></tr><tr><td>Variação de distância</td><td>Controle de profundidade</td><td>80% dentro de 50 cm</td></tr></tbody></table><h3 id="acompanhando-suas-medidas" tabindex="-1">Acompanhando suas medidas <a class="header-anchor" href="#acompanhando-suas-medidas" aria-label="Permalink to &quot;Acompanhando suas medidas&quot;">​</a></h3><p>Mantenha um registro simples:</p><ul><li>Data</li><li>Exercício/treinamento</li><li>Pontuação/resultado</li><li>Condições (superfície, clima)</li><li>Notas</li></ul><h2 id="a-atingivel-mas-desafiador" tabindex="-1">A - Atingível (mas desafiador) <a class="header-anchor" href="#a-atingivel-mas-desafiador" aria-label="Permalink to &quot;A - Atingível (mas desafiador)&quot;">​</a></h2><p>Os objetivos devem te desafiar sem serem impossíveis.</p><h3 id="encontrando-o-nivel-certo" tabindex="-1">Encontrando o nível certo <a class="header-anchor" href="#encontrando-o-nivel-certo" aria-label="Permalink to &quot;Encontrando o nível certo&quot;">​</a></h3><p><strong>Muito fácil:</strong> &quot;Pratique uma vez este mês&quot;</p><ul><li>Sem crescimento, sem motivação.</li></ul><p><strong>Muito difícil:</strong> &quot;Nunca erre um arremesso&quot;</p><ul><li>Impossível leva à frustração.</li></ul><p><strong>Ideal:</strong> &quot;Aumente a precisão dos seus tiros em 15% em 8 semanas&quot;</p><ul><li>Desafiador, mas realista com esforço.</li></ul><h3 id="questoes-para-testar-a-capacidade-de-realizacao" tabindex="-1">Questões para testar a capacidade de realização <a class="header-anchor" href="#questoes-para-testar-a-capacidade-de-realizacao" aria-label="Permalink to &quot;Questões para testar a capacidade de realização&quot;">​</a></h3><ul><li>Outros indivíduos do meu nível já conseguiram isso?</li><li>Tenho o tempo e os recursos necessários?</li><li>Isso está (em grande parte) sob meu controle?</li><li>Estou disposto a fazer o que for preciso?</li></ul><h3 id="metas-ambiciosas" tabindex="-1">Metas ambiciosas <a class="header-anchor" href="#metas-ambiciosas" aria-label="Permalink to &quot;Metas ambiciosas&quot;">​</a></h3><p>Ter objetivos ambiciosos a longo prazo é normal. Apenas certifique-se de que seus objetivos a curto prazo sejam passos alcançáveis em direção a eles.</p><h2 id="r-relevante" tabindex="-1">R - Relevante <a class="header-anchor" href="#r-relevante" aria-label="Permalink to &quot;R - Relevante&quot;">​</a></h2><p>Seus objetivos devem estar alinhados com sua visão de longo prazo.</p><h3 id="questoes-de-relevancia" tabindex="-1">Questões de Relevância <a class="header-anchor" href="#questoes-de-relevancia" aria-label="Permalink to &quot;Questões de Relevância&quot;">​</a></h3><ul><li>Este objetivo contribui para o meu desenvolvimento geral?</li><li>Essa é a prioridade certa neste momento?</li><li>Isso se encaixa no meu tempo e recursos disponíveis?</li><li>Estou realmente motivado por esse objetivo?</li></ul><h3 id="exemplo-verificando-a-relevancia" tabindex="-1">Exemplo: Verificando a Relevância <a class="header-anchor" href="#exemplo-verificando-a-relevancia" aria-label="Permalink to &quot;Exemplo: Verificando a Relevância&quot;">​</a></h3><p><strong>Situação:</strong> Você deseja competir em nível nacional.</p><p><strong>Objetivos relevantes:</strong></p><ul><li>Melhorar a precisão dos disparos (impacta diretamente os resultados)</li><li>Desenvolva rotinas mentais (ajuda em situações de pressão)</li><li>Aumentar a frequência de treino (desenvolve a habilidade mais rapidamente)</li></ul><p><strong>Objetivos menos relevantes:</strong></p><ul><li>Aprenda jogadas de efeito (diversão, mas não prioridade competitiva)</li><li>Compre bolas novas e caras (o equipamento não é o seu fator limitante).</li></ul><h2 id="t-temporal" tabindex="-1">T - Temporal <a class="header-anchor" href="#t-temporal" aria-label="Permalink to &quot;T - Temporal&quot;">​</a></h2><p>Os prazos criam urgência e possibilitam o planejamento.</p><h3 id="definir-prazos" tabindex="-1">Definir prazos <a class="header-anchor" href="#definir-prazos" aria-label="Permalink to &quot;Definir prazos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo de objetivo</th><th>Prazo típico</th></tr></thead><tbody><tr><td>Longo prazo</td><td>1 a 3 anos</td></tr><tr><td>Anual</td><td>12 meses</td></tr><tr><td>Trimestral</td><td>3 meses</td></tr><tr><td>Mensal</td><td>4 semanas</td></tr><tr><td>Semanalmente</td><td>7 dias</td></tr><tr><td>Sessão</td><td>Prática individual</td></tr></tbody></table><h3 id="exemplo-de-linha-do-tempo" tabindex="-1">Exemplo de linha do tempo <a class="header-anchor" href="#exemplo-de-linha-do-tempo" aria-label="Permalink to &quot;Exemplo de linha do tempo&quot;">​</a></h3><p><strong>Longo prazo (2 anos):</strong> Qualificar-se para a seleção da equipe nacional</p><p><strong>Anual:</strong> Ficar entre os 10 primeiros colocados no ranking regional</p><p><strong>Trimestral (1º trimestre):</strong></p><ul><li>Estabeleça uma rotina de treinamento consistente.</li><li>Melhore a precisão dos seus disparos para 70%.</li></ul><p><strong>Mensal (janeiro):</strong></p><ul><li>Semana 1: Avaliar o nível atual, definir parâmetros de referência.</li><li>Semanas 2 e 3: Foco na técnica de arremesso</li><li>Semana 4: Testar e medir o progresso</li></ul><p><strong>Semanalmente:</strong></p><ul><li>Segunda-feira: Sessão de filmagem técnica</li><li>Quarta-feira: Apontar e situações de jogo</li><li>Sexta-feira: Treinamento mental e visualização</li><li>Fim de semana: Competição ou treino para jogo</li></ul><h2 id="juntando-tudo" tabindex="-1">Juntando tudo <a class="header-anchor" href="#juntando-tudo" aria-label="Permalink to &quot;Juntando tudo&quot;">​</a></h2><h3 id="planilha-para-definicao-de-metas" tabindex="-1">Planilha para definição de metas <a class="header-anchor" href="#planilha-para-definicao-de-metas" aria-label="Permalink to &quot;Planilha para definição de metas&quot;">​</a></h3><p><strong>Meu objetivo (primeira versão):</strong></p><hr><p><strong>Específico - O quê exatamente?</strong></p><hr><p><strong>Mensurável - Como saberei?</strong></p><hr><p><strong>Viável - É realista?</strong></p><hr><p><strong>Relevante - Por que isso importa?</strong></p><hr><p><strong>Com prazo definido - Até quando?</strong></p><hr><p><strong>Minha meta SMART (versão final):</strong></p><hr><h3 id="exemplo-concluido" tabindex="-1">Exemplo concluído <a class="header-anchor" href="#exemplo-concluido" aria-label="Permalink to &quot;Exemplo concluído&quot;">​</a></h3><p><strong>Primeira versão:</strong> &quot;Aprimorar a pontaria&quot;</p><p><strong>Versão SMART:</strong> &quot;Até 30 de abril, alcançarei uma pontuação de 24/30 ou superior no exercício de Escada de Tiro (6-10m com obstáculos) em três sessões de treinamento consecutivas, conforme registrado em meu diário de treinamento.&quot;</p><h2 id="ponto-chave" tabindex="-1">Ponto-chave <a class="header-anchor" href="#ponto-chave" aria-label="Permalink to &quot;Ponto-chave&quot;">​</a></h2><blockquote><p>Metas SMART transformam sonhos em planos e planos em resultados.</p></blockquote><p>Dedique tempo para elaborar seus objetivos com cuidado. Um objetivo bem definido é metade do caminho percorrido.</p>',75))])}]]);export{m as __pageData,p as default};
